#!/bin/sh
out=SUMMARY.txt
if [ "$1" = "-o" ]; then out="$2"; shift 2; fi
{
  printf 'COMPRESSED %s path(s) at ' "$#"
  date -u +%Y-%m-%dT%H:%M:%SZ
  for p in "$@"; do printf -- '- %s\n' "$p"; done
} > "$out"
echo "wrote $out"

